using Godot;

/// <summary>使用 MultiMesh 批绘制六边形平原植被，并支持按格清除和砍伐树木。</summary>
public partial class VegetationLayer : Node2D
{
    [Export] public float grass_scale_min=.08f,grass_scale_max=.16f,tree_scale_min=.5f,tree_scale_max=.8f;
    private static readonly string[] TreePaths=["res://textures/树/1f505722fb564aef8afbd7b1589bffd1.jpeg~tplv-a9rns2rl98-downsize_watermark_1_5.png","res://textures/树/92c674e2dbfc46ee8582bb4876ba015b.jpeg~tplv-a9rns2rl98-downsize_watermark_1_5.png","res://textures/树/15141316605049c1a7b4dc54b956b9f5.jpeg~tplv-a9rns2rl98-downsize_watermark_1_5.png","res://textures/树/a3d899143b3c4b6694839625ba7e8754.jpeg~tplv-a9rns2rl98-downsize_watermark_1_5.png","res://textures/树/af8caa7eb60849c196f99622f1c224fc.jpeg~tplv-a9rns2rl98-downsize_watermark_1_5.png","res://textures/树/f5a939d9a8ee4f568ec0e950425ef9f1.jpeg~tplv-a9rns2rl98-downsize_watermark_1_5.png"];
    private readonly List<Texture2D> textures=[]; private readonly List<(MultiMesh Mesh,Texture2D Texture)> draws=[]; private readonly Dictionary<Vector2I,List<(int Bucket,int Index)>> refs=[]; private GodotObject? map;
    public override void _Ready(){YSortEnabled=true;var parent=GetParent<Node2D>();if(parent is not null&&!Mathf.IsZeroApprox(parent.Scale.Y)&&!Mathf.IsEqualApprox(parent.Scale.Y,1))Scale=new(1,1/parent.Scale.Y);foreach(var path in TreePaths)if(ResourceLoader.Exists(path)&&ResourceLoader.Load<Texture2D>(path) is { } texture)textures.Add(texture);CallDeferred(nameof(find_map));}
    private void find_map(){foreach(var node in GetTree().GetNodesInGroup("hex_world_map")){map=node;break;}if(GodotObject.IsInstanceValid(map))scatter_all();}
    public void scatter_all(){if(!GodotObject.IsInstanceValid(map)||textures.Count==0)return;clear_vegetation();var buckets=Enumerable.Range(0,textures.Count).Select(_=>new List<(Vector2 Position,float Scale,float Rotation)>()).ToArray();var rng=new RandomNumberGenerator();rng.Randomize();foreach(var item in map!.Get("cells").AsGodotDictionary().Keys){var cell=item.AsVector2I();if(map.Call("get_terrain_type",cell).AsInt32()!=0||map.Call("get_fertility",cell).AsSingle()<.7f)continue;var count=rng.RandiRange(1,map.Call("get_fertility",cell).AsSingle()>.85f?2:1);var cellRefs=new List<(int,int)>();var center=map.Call("cell_to_world",cell).AsVector2();var radius=map.Get("hex_size").AsSingle()*.7f;for(var i=0;i<count;i++){var bucket=rng.RandiRange(0,textures.Count-1);var scale=Mathf.Lerp(tree_scale_min,tree_scale_max,rng.Randf());var angle=rng.RandfRange(0,Mathf.Tau);var distance=rng.RandfRange(0,radius);var position=center+new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*distance;position.Y-=textures[bucket].GetHeight()*scale*.5f;cellRefs.Add((bucket,buckets[bucket].Count));buckets[bucket].Add((position,scale,rng.RandfRange(-.15f,.15f)));}if(cellRefs.Count>0)refs[cell]=cellRefs;}for(var i=0;i<buckets.Length;i++)if(buckets[i].Count>0)draws.Add((build_mesh(textures[i],buckets[i]),textures[i]));QueueRedraw();}
    private MultiMesh build_mesh(Texture2D texture,List<(Vector2 Position,float Scale,float Rotation)> items){var mesh=new MultiMesh{TransformFormat=MultiMesh.TransformFormatEnum.Transform2D,InstanceCount=items.Count,Mesh=new QuadMesh{Size=new(texture.GetWidth(),texture.GetHeight())}};for(var i=0;i<items.Count;i++){var item=items[i];mesh.SetInstanceTransform2D(i,new Transform2D(item.Rotation,new Vector2(item.Scale,-item.Scale),0,ToLocal(item.Position)));}return mesh;}
    public override void _Draw(){foreach(var draw in draws)DrawMultimesh(draw.Mesh,draw.Texture);}
    public void clear_cell(Vector2I cell){if(!refs.TryGetValue(cell,out var values))return;foreach(var value in values)hide(value);refs.Remove(cell);}
    public bool has_trees(Vector2I cell)=>refs.TryGetValue(cell,out var values)&&values.Any(value=>visible(value));
    public int chop_trees(Vector2I cell){if(!refs.TryGetValue(cell,out var values))return 0;var total=0;foreach(var value in values)if(visible(value)){hide(value);total++;}return total;}
    private bool visible((int Bucket,int Index) reference)=>reference.Bucket>=0&&reference.Bucket<draws.Count&&draws[reference.Bucket].Mesh.GetInstanceTransform2D(reference.Index).Scale.X>.001f;
    private void hide((int Bucket,int Index) reference){if(reference.Bucket<0||reference.Bucket>=draws.Count)return;var mesh=draws[reference.Bucket].Mesh;mesh.SetInstanceTransform2D(reference.Index,mesh.GetInstanceTransform2D(reference.Index).Scaled(Vector2.Zero));}
    public void clear_vegetation(){draws.Clear();refs.Clear();QueueRedraw();}
    public void refresh(){clear_vegetation();scatter_all();}
}
